"use strict";(globalThis.webpackChunkgrc||=[]).push([[34275],{82112(e){e.exports=JSON.parse('{"citeKey":"chanchio2001communicationstate","slug":"chanchio-2001-communication-state-e392","title":"Communication State Transfer for the Mobility of Concurrent Heterogenous Computing","authors":["K. Chanchio","X.-H. Sun"],"venue":"The 2001 the International Conference on Parallel Processing (ICPP 2001) Best Paper Award","type":"Conference","entryType":"inproceedings","date":"September, 2001","year":2001,"era":"iit","month":9,"doi":"10.1109/icpp.2001.952087","abstract":"In a dynamic environment, where a process can be migrated from one host to an- other host, communication state transfer is a key issue of process coordination. This paper presents algorithms for data communication and migration protocols to support communication state transfer in a dynamic, distributed parallel environment. These algorithms collectively preserve the semantics of the communication and support com- munication state transfer. The assumptions and validity of our solution are discussed and analyzed. Based on our early results in process migration, we implement a proto- type system for process state transfer. Experimental results confirm our design is valid and has a true potential in practice.","hasAbstract":true,"lede":"This paper presents algorithms for data communication and migration protocols to support communication state transfer in a dynamic, distributed parallel environment.","links":{"pdf":"https://grc.iit.edu/papers/2001/chanchio-2001-communication-state-e392.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hpcm"],"memberAuthors":["sun-xian-he"]}')}}]);